INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഇന്റർനെറ്റ് വഴി കണക്കുകൂട്ടൽ വിഭവങ്ങൾ ആവശ്യാനുസരണം ഉപയോഗിക്കുന്ന രീതി.',ARRAY['മേഘ കണക്കുകൂട്ടൽ','സമൂഹ മേഘം','വിഭവ വികസനം','വസ്തു സംഭരണം'],'മേഘ കണക്കുകൂട്ടൽ','ശരിയായ ഉത്തരം മേഘ കണക്കുകൂട്ടൽ ആണ്. ഇന്റർനെറ്റ് വഴി കണക്കുകൂട്ടൽ വിഭവങ്ങൾ ആവശ്യാനുസരണം ഉപയോഗിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? കണക്കുകൂട്ടൽ യന്ത്രങ്ങൾ സംഭരണം ശൃംഖല തുടങ്ങിയ അടിസ്ഥാന വിഭവങ്ങൾ സേവനമായി ലഭ്യമാക്കുന്ന മാതൃക.',ARRAY['സേവനമായി അടിസ്ഥാനസൗകര്യം','വിർച്വലൈസേഷൻ','വിഭവ വ്യാപനം','ഫയൽ സംഭരണം'],'സേവനമായി അടിസ്ഥാനസൗകര്യം','ശരിയായ ഉത്തരം സേവനമായി അടിസ്ഥാനസൗകര്യം ആണ്. കണക്കുകൂട്ടൽ യന്ത്രങ്ങൾ സംഭരണം ശൃംഖല തുടങ്ങിയ അടിസ്ഥാന വിഭവങ്ങൾ സേവനമായി ലഭ്യമാക്കുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? പ്രയോഗങ്ങൾ വികസിപ്പിക്കാനും പ്രവർത്തിപ്പിക്കാനും ആവശ്യമായ വേദി സേവനമായി നൽകുന്ന മാതൃക.',ARRAY['സേവനമായി വേദി','വിർച്വൽ യന്ത്രം','ഭാരം വിതരണം','ഖണ്ഡ സംഭരണം'],'സേവനമായി വേദി','ശരിയായ ഉത്തരം സേവനമായി വേദി ആണ്. പ്രയോഗങ്ങൾ വികസിപ്പിക്കാനും പ്രവർത്തിപ്പിക്കാനും ആവശ്യമായ വേദി സേവനമായി നൽകുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സജ്ജമായ പ്രയോഗം സേവനമായി ഉപയോഗിക്കാൻ നൽകുന്ന മാതൃക.',ARRAY['സേവനമായി സോഫ്റ്റ്‌വെയർ','കണ്ടെയ്നർ','ലഭ്യത','മേഘ ശൃംഖല'],'സേവനമായി സോഫ്റ്റ്‌വെയർ','ശരിയായ ഉത്തരം സേവനമായി സോഫ്റ്റ്‌വെയർ ആണ്. സജ്ജമായ പ്രയോഗം സേവനമായി ഉപയോഗിക്കാൻ നൽകുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? പല ഉപയോക്താക്കൾക്കും പങ്കിട്ട അടിസ്ഥാനസൗകര്യത്തിൽ ലഭ്യമാകുന്ന മേഘ മാതൃക.',ARRAY['പൊതു മേഘം','കണ്ടെയ്നർ ക്രമീകരണം','വിശ്വാസ്യത','സ്വകാര്യ ശൃംഖല'],'പൊതു മേഘം','ശരിയായ ഉത്തരം പൊതു മേഘം ആണ്. പല ഉപയോക്താക്കൾക്കും പങ്കിട്ട അടിസ്ഥാനസൗകര്യത്തിൽ ലഭ്യമാകുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക.',ARRAY['സ്വകാര്യ മേഘം','സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി','സേവന നിലവാര കരാർ','ഉപശൃംഖല'],'സ്വകാര്യ മേഘം','ശരിയായ ഉത്തരം സ്വകാര്യ മേഘം ആണ്. ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക.',ARRAY['മിശ്ര മേഘം','വിഭവ വികസനം','വിഭവ നിരീക്ഷണം','അഗ്നിരോധ മതിൽ'],'മിശ്ര മേഘം','ശരിയായ ഉത്തരം മിശ്ര മേഘം ആണ്. പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക.',ARRAY['സമൂഹ മേഘം','വിഭവ വ്യാപനം','മേഘ സംഭരണം','അനുമതി നിയന്ത്രണം'],'സമൂഹ മേഘം','ശരിയായ ഉത്തരം സമൂഹ മേഘം ആണ്. സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ.',ARRAY['വിർച്വലൈസേഷൻ','ഭാരം വിതരണം','വസ്തു സംഭരണം','തിരിച്ചറിയൽ പരിശോധന'],'വിർച്വലൈസേഷൻ','ശരിയായ ഉത്തരം വിർച്വലൈസേഷൻ ആണ്. ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം.',ARRAY['വിർച്വൽ യന്ത്രം','ലഭ്യത','ഫയൽ സംഭരണം','ബഹുഘടക തിരിച്ചറിയൽ'],'വിർച്വൽ യന്ത്രം','ശരിയായ ഉത്തരം വിർച്വൽ യന്ത്രം ആണ്. ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം.',ARRAY['കണ്ടെയ്നർ','വിശ്വാസ്യത','ഖണ്ഡ സംഭരണം','ഡാറ്റ എൻക്രിപ്ഷൻ'],'കണ്ടെയ്നർ','ശരിയായ ഉത്തരം കണ്ടെയ്നർ ആണ്. പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം.',ARRAY['കണ്ടെയ്നർ ക്രമീകരണം','സേവന നിലവാര കരാർ','മേഘ ശൃംഖല','ഡാറ്റ പകർപ്പ്'],'കണ്ടെയ്നർ ക്രമീകരണം','ശരിയായ ഉത്തരം കണ്ടെയ്നർ ക്രമീകരണം ആണ്. പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്.',ARRAY['സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി','വിഭവ നിരീക്ഷണം','സ്വകാര്യ ശൃംഖല','ബാക്കപ്പ്'],'സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി','ശരിയായ ഉത്തരം സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി ആണ്. ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി.',ARRAY['വിഭവ വികസനം','മേഘ സംഭരണം','ഉപശൃംഖല','ദുരന്ത വീണ്ടെടുക്കൽ'],'വിഭവ വികസനം','ശരിയായ ഉത്തരം വിഭവ വികസനം ആണ്. കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി.',ARRAY['വിഭവ വ്യാപനം','വസ്തു സംഭരണം','അഗ്നിരോധ മതിൽ','പ്രവർത്തന തുടർച്ച'],'വിഭവ വ്യാപനം','ശരിയായ ഉത്തരം വിഭവ വ്യാപനം ആണ്. കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി.',ARRAY['ഭാരം വിതരണം','ഫയൽ സംഭരണം','അനുമതി നിയന്ത്രണം','മേഘ കുടിയേറ്റം'],'ഭാരം വിതരണം','ശരിയായ ഉത്തരം ഭാരം വിതരണം ആണ്. പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ.',ARRAY['ലഭ്യത','ഖണ്ഡ സംഭരണം','തിരിച്ചറിയൽ പരിശോധന','മേഘ ചെലവ് നിയന്ത്രണം'],'ലഭ്യത','ശരിയായ ഉത്തരം ലഭ്യത ആണ്. ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്.',ARRAY['വിശ്വാസ്യത','മേഘ ശൃംഖല','ബഹുഘടക തിരിച്ചറിയൽ','സർവർ രഹിത കണക്കുകൂട്ടൽ'],'വിശ്വാസ്യത','ശരിയായ ഉത്തരം വിശ്വാസ്യത ആണ്. ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ.',ARRAY['സേവന നിലവാര കരാർ','സ്വകാര്യ ശൃംഖല','ഡാറ്റ എൻക്രിപ്ഷൻ','അറ്റ കണക്കുകൂട്ടൽ'],'സേവന നിലവാര കരാർ','ശരിയായ ഉത്തരം സേവന നിലവാര കരാർ ആണ്. സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം.',ARRAY['വിഭവ നിരീക്ഷണം','ഉപശൃംഖല','ഡാറ്റ പകർപ്പ്','മേഘ കണക്കുകൂട്ടൽ'],'വിഭവ നിരീക്ഷണം','ശരിയായ ഉത്തരം വിഭവ നിരീക്ഷണം ആണ്. കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം.',ARRAY['മേഘ സംഭരണം','അഗ്നിരോധ മതിൽ','ബാക്കപ്പ്','സേവനമായി അടിസ്ഥാനസൗകര്യം'],'മേഘ സംഭരണം','ശരിയായ ഉത്തരം മേഘ സംഭരണം ആണ്. ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.',ARRAY['വസ്തു സംഭരണം','അനുമതി നിയന്ത്രണം','ദുരന്ത വീണ്ടെടുക്കൽ','സേവനമായി വേദി'],'വസ്തു സംഭരണം','ശരിയായ ഉത്തരം വസ്തു സംഭരണം ആണ്. ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.',ARRAY['ഫയൽ സംഭരണം','തിരിച്ചറിയൽ പരിശോധന','പ്രവർത്തന തുടർച്ച','സേവനമായി സോഫ്റ്റ്‌വെയർ'],'ഫയൽ സംഭരണം','ശരിയായ ഉത്തരം ഫയൽ സംഭരണം ആണ്. ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.',ARRAY['ഖണ്ഡ സംഭരണം','ബഹുഘടക തിരിച്ചറിയൽ','മേഘ കുടിയേറ്റം','പൊതു മേഘം'],'ഖണ്ഡ സംഭരണം','ശരിയായ ഉത്തരം ഖണ്ഡ സംഭരണം ആണ്. ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല.',ARRAY['മേഘ ശൃംഖല','ഡാറ്റ എൻക്രിപ്ഷൻ','മേഘ ചെലവ് നിയന്ത്രണം','സ്വകാര്യ മേഘം'],'മേഘ ശൃംഖല','ശരിയായ ഉത്തരം മേഘ ശൃംഖല ആണ്. മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി.',ARRAY['സ്വകാര്യ ശൃംഖല','ഡാറ്റ പകർപ്പ്','സർവർ രഹിത കണക്കുകൂട്ടൽ','മിശ്ര മേഘം'],'സ്വകാര്യ ശൃംഖല','ശരിയായ ഉത്തരം സ്വകാര്യ ശൃംഖല ആണ്. ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം.',ARRAY['ഉപശൃംഖല','ബാക്കപ്പ്','അറ്റ കണക്കുകൂട്ടൽ','സമൂഹ മേഘം'],'ഉപശൃംഖല','ശരിയായ ഉത്തരം ഉപശൃംഖല ആണ്. വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം.',ARRAY['അഗ്നിരോധ മതിൽ','ദുരന്ത വീണ്ടെടുക്കൽ','മേഘ കണക്കുകൂട്ടൽ','വിർച്വലൈസേഷൻ'],'അഗ്നിരോധ മതിൽ','ശരിയായ ഉത്തരം അഗ്നിരോധ മതിൽ ആണ്. അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം.',ARRAY['അനുമതി നിയന്ത്രണം','പ്രവർത്തന തുടർച്ച','സേവനമായി അടിസ്ഥാനസൗകര്യം','വിർച്വൽ യന്ത്രം'],'അനുമതി നിയന്ത്രണം','ശരിയായ ഉത്തരം അനുമതി നിയന്ത്രണം ആണ്. ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ.',ARRAY['തിരിച്ചറിയൽ പരിശോധന','മേഘ കുടിയേറ്റം','സേവനമായി വേദി','കണ്ടെയ്നർ'],'തിരിച്ചറിയൽ പരിശോധന','ശരിയായ ഉത്തരം തിരിച്ചറിയൽ പരിശോധന ആണ്. ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിച്ച് ഉപയോക്താവിനെ സ്ഥിരീകരിക്കുന്ന രീതി.',ARRAY['ബഹുഘടക തിരിച്ചറിയൽ','മേഘ ചെലവ് നിയന്ത്രണം','സേവനമായി സോഫ്റ്റ്‌വെയർ','കണ്ടെയ്നർ ക്രമീകരണം'],'ബഹുഘടക തിരിച്ചറിയൽ','ശരിയായ ഉത്തരം ബഹുഘടക തിരിച്ചറിയൽ ആണ്. ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിച്ച് ഉപയോക്താവിനെ സ്ഥിരീകരിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി.',ARRAY['ഡാറ്റ എൻക്രിപ്ഷൻ','സർവർ രഹിത കണക്കുകൂട്ടൽ','പൊതു മേഘം','സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി'],'ഡാറ്റ എൻക്രിപ്ഷൻ','ശരിയായ ഉത്തരം ഡാറ്റ എൻക്രിപ്ഷൻ ആണ്. ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി.',ARRAY['ഡാറ്റ പകർപ്പ്','അറ്റ കണക്കുകൂട്ടൽ','സ്വകാര്യ മേഘം','വിഭവ വികസനം'],'ഡാറ്റ പകർപ്പ്','ശരിയായ ഉത്തരം ഡാറ്റ പകർപ്പ് ആണ്. ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ.',ARRAY['ബാക്കപ്പ്','മേഘ കണക്കുകൂട്ടൽ','മിശ്ര മേഘം','വിഭവ വ്യാപനം'],'ബാക്കപ്പ്','ശരിയായ ഉത്തരം ബാക്കപ്പ് ആണ്. വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം.',ARRAY['ദുരന്ത വീണ്ടെടുക്കൽ','സേവനമായി അടിസ്ഥാനസൗകര്യം','സമൂഹ മേഘം','ഭാരം വിതരണം'],'ദുരന്ത വീണ്ടെടുക്കൽ','ശരിയായ ഉത്തരം ദുരന്ത വീണ്ടെടുക്കൽ ആണ്. വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? തടസ്സങ്ങൾ ഉണ്ടായാലും പ്രധാന സേവനങ്ങൾ തുടരാൻ സഹായിക്കുന്ന പദ്ധതി.',ARRAY['പ്രവർത്തന തുടർച്ച','സേവനമായി വേദി','വിർച്വലൈസേഷൻ','ലഭ്യത'],'പ്രവർത്തന തുടർച്ച','ശരിയായ ഉത്തരം പ്രവർത്തന തുടർച്ച ആണ്. തടസ്സങ്ങൾ ഉണ്ടായാലും പ്രധാന സേവനങ്ങൾ തുടരാൻ സഹായിക്കുന്ന പദ്ധതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? പ്രയോഗങ്ങളെയോ ഡാറ്റയെയോ മേഘ പരിസ്ഥിതിയിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.',ARRAY['മേഘ കുടിയേറ്റം','സേവനമായി സോഫ്റ്റ്‌വെയർ','വിർച്വൽ യന്ത്രം','വിശ്വാസ്യത'],'മേഘ കുടിയേറ്റം','ശരിയായ ഉത്തരം മേഘ കുടിയേറ്റം ആണ്. പ്രയോഗങ്ങളെയോ ഡാറ്റയെയോ മേഘ പരിസ്ഥിതിയിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? മേഘ വിഭവങ്ങളുടെ ഉപയോഗവും ചെലവും കാര്യക്ഷമമായി നിയന്ത്രിക്കുന്ന പ്രവർത്തനം.',ARRAY['മേഘ ചെലവ് നിയന്ത്രണം','പൊതു മേഘം','കണ്ടെയ്നർ','സേവന നിലവാര കരാർ'],'മേഘ ചെലവ് നിയന്ത്രണം','ശരിയായ ഉത്തരം മേഘ ചെലവ് നിയന്ത്രണം ആണ്. മേഘ വിഭവങ്ങളുടെ ഉപയോഗവും ചെലവും കാര്യക്ഷമമായി നിയന്ത്രിക്കുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സെർവർ പരിപാലനം ഉപയോക്താവിൽ നിന്ന് മറച്ച് ആവശ്യാനുസരണം പ്രയോഗ പ്രവർത്തനം നടത്തിക്കുന്ന മാതൃക.',ARRAY['സർവർ രഹിത കണക്കുകൂട്ടൽ','സ്വകാര്യ മേഘം','കണ്ടെയ്നർ ക്രമീകരണം','വിഭവ നിരീക്ഷണം'],'സർവർ രഹിത കണക്കുകൂട്ടൽ','ശരിയായ ഉത്തരം സർവർ രഹിത കണക്കുകൂട്ടൽ ആണ്. സെർവർ പരിപാലനം ഉപയോക്താവിൽ നിന്ന് മറച്ച് ആവശ്യാനുസരണം പ്രയോഗ പ്രവർത്തനം നടത്തിക്കുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഡാറ്റയുടെ ഉറവിടത്തിന് സമീപം കണക്കുകൂട്ടൽ നടത്തിക്കുന്ന രീതി.',ARRAY['അറ്റ കണക്കുകൂട്ടൽ','മിശ്ര മേഘം','സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി','മേഘ സംഭരണം'],'അറ്റ കണക്കുകൂട്ടൽ','ശരിയായ ഉത്തരം അറ്റ കണക്കുകൂട്ടൽ ആണ്. ഡാറ്റയുടെ ഉറവിടത്തിന് സമീപം കണക്കുകൂട്ടൽ നടത്തിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ മേഘ കണക്കുകൂട്ടൽയും സേവനമായി അടിസ്ഥാനസൗകര്യംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['മേഘ കണക്കുകൂട്ടൽ: ഇന്റർനെറ്റ് വഴി കണക്കുകൂട്ടൽ വിഭവങ്ങൾ ആവശ്യാനുസരണം ഉപയോഗിക്കുന്ന രീതി','സേവനമായി അടിസ്ഥാനസൗകര്യം: കണക്കുകൂട്ടൽ യന്ത്രങ്ങൾ സംഭരണം ശൃംഖല തുടങ്ങിയ അടിസ്ഥാന വിഭവങ്ങൾ സേവനമായി ലഭ്യമാക്കുന്ന മാതൃക','സേവനമായി വേദി: പ്രയോഗങ്ങൾ വികസിപ്പിക്കാനും പ്രവർത്തിപ്പിക്കാനും ആവശ്യമായ വേദി സേവനമായി നൽകുന്ന മാതൃക','കണ്ടെയ്നർ ക്രമീകരണം: പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം'],'മേഘ കണക്കുകൂട്ടൽ; സേവനമായി അടിസ്ഥാനസൗകര്യം','മേഘ കണക്കുകൂട്ടൽ: ഇന്റർനെറ്റ് വഴി കണക്കുകൂട്ടൽ വിഭവങ്ങൾ ആവശ്യാനുസരണം ഉപയോഗിക്കുന്ന രീതി. സേവനമായി അടിസ്ഥാനസൗകര്യം: കണക്കുകൂട്ടൽ യന്ത്രങ്ങൾ സംഭരണം ശൃംഖല തുടങ്ങിയ അടിസ്ഥാന വിഭവങ്ങൾ സേവനമായി ലഭ്യമാക്കുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സേവനമായി അടിസ്ഥാനസൗകര്യംയും സേവനമായി വേദിയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സേവനമായി അടിസ്ഥാനസൗകര്യം: കണക്കുകൂട്ടൽ യന്ത്രങ്ങൾ സംഭരണം ശൃംഖല തുടങ്ങിയ അടിസ്ഥാന വിഭവങ്ങൾ സേവനമായി ലഭ്യമാക്കുന്ന മാതൃക','സേവനമായി വേദി: പ്രയോഗങ്ങൾ വികസിപ്പിക്കാനും പ്രവർത്തിപ്പിക്കാനും ആവശ്യമായ വേദി സേവനമായി നൽകുന്ന മാതൃക','സേവനമായി സോഫ്റ്റ്‌വെയർ: സജ്ജമായ പ്രയോഗം സേവനമായി ഉപയോഗിക്കാൻ നൽകുന്ന മാതൃക','സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി: ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്'],'സേവനമായി അടിസ്ഥാനസൗകര്യം; സേവനമായി വേദി','സേവനമായി അടിസ്ഥാനസൗകര്യം: കണക്കുകൂട്ടൽ യന്ത്രങ്ങൾ സംഭരണം ശൃംഖല തുടങ്ങിയ അടിസ്ഥാന വിഭവങ്ങൾ സേവനമായി ലഭ്യമാക്കുന്ന മാതൃക. സേവനമായി വേദി: പ്രയോഗങ്ങൾ വികസിപ്പിക്കാനും പ്രവർത്തിപ്പിക്കാനും ആവശ്യമായ വേദി സേവനമായി നൽകുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സേവനമായി വേദിയും സേവനമായി സോഫ്റ്റ്‌വെയർയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സേവനമായി വേദി: പ്രയോഗങ്ങൾ വികസിപ്പിക്കാനും പ്രവർത്തിപ്പിക്കാനും ആവശ്യമായ വേദി സേവനമായി നൽകുന്ന മാതൃക','സേവനമായി സോഫ്റ്റ്‌വെയർ: സജ്ജമായ പ്രയോഗം സേവനമായി ഉപയോഗിക്കാൻ നൽകുന്ന മാതൃക','പൊതു മേഘം: പല ഉപയോക്താക്കൾക്കും പങ്കിട്ട അടിസ്ഥാനസൗകര്യത്തിൽ ലഭ്യമാകുന്ന മേഘ മാതൃക','വിഭവ വികസനം: കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി'],'സേവനമായി വേദി; സേവനമായി സോഫ്റ്റ്‌വെയർ','സേവനമായി വേദി: പ്രയോഗങ്ങൾ വികസിപ്പിക്കാനും പ്രവർത്തിപ്പിക്കാനും ആവശ്യമായ വേദി സേവനമായി നൽകുന്ന മാതൃക. സേവനമായി സോഫ്റ്റ്‌വെയർ: സജ്ജമായ പ്രയോഗം സേവനമായി ഉപയോഗിക്കാൻ നൽകുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സേവനമായി സോഫ്റ്റ്‌വെയർയും പൊതു മേഘംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സേവനമായി സോഫ്റ്റ്‌വെയർ: സജ്ജമായ പ്രയോഗം സേവനമായി ഉപയോഗിക്കാൻ നൽകുന്ന മാതൃക','പൊതു മേഘം: പല ഉപയോക്താക്കൾക്കും പങ്കിട്ട അടിസ്ഥാനസൗകര്യത്തിൽ ലഭ്യമാകുന്ന മേഘ മാതൃക','സ്വകാര്യ മേഘം: ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക','വിഭവ വ്യാപനം: കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി'],'സേവനമായി സോഫ്റ്റ്‌വെയർ; പൊതു മേഘം','സേവനമായി സോഫ്റ്റ്‌വെയർ: സജ്ജമായ പ്രയോഗം സേവനമായി ഉപയോഗിക്കാൻ നൽകുന്ന മാതൃക. പൊതു മേഘം: പല ഉപയോക്താക്കൾക്കും പങ്കിട്ട അടിസ്ഥാനസൗകര്യത്തിൽ ലഭ്യമാകുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ പൊതു മേഘംയും സ്വകാര്യ മേഘംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['പൊതു മേഘം: പല ഉപയോക്താക്കൾക്കും പങ്കിട്ട അടിസ്ഥാനസൗകര്യത്തിൽ ലഭ്യമാകുന്ന മേഘ മാതൃക','സ്വകാര്യ മേഘം: ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക','മിശ്ര മേഘം: പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക','ഭാരം വിതരണം: പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി'],'പൊതു മേഘം; സ്വകാര്യ മേഘം','പൊതു മേഘം: പല ഉപയോക്താക്കൾക്കും പങ്കിട്ട അടിസ്ഥാനസൗകര്യത്തിൽ ലഭ്യമാകുന്ന മേഘ മാതൃക. സ്വകാര്യ മേഘം: ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സ്വകാര്യ മേഘംയും മിശ്ര മേഘംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സ്വകാര്യ മേഘം: ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക','മിശ്ര മേഘം: പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക','സമൂഹ മേഘം: സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക','ലഭ്യത: ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ'],'സ്വകാര്യ മേഘം; മിശ്ര മേഘം','സ്വകാര്യ മേഘം: ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക. മിശ്ര മേഘം: പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ മിശ്ര മേഘംയും സമൂഹ മേഘംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['മിശ്ര മേഘം: പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക','സമൂഹ മേഘം: സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക','വിർച്വലൈസേഷൻ: ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ','വിശ്വാസ്യത: ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്'],'മിശ്ര മേഘം; സമൂഹ മേഘം','മിശ്ര മേഘം: പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക. സമൂഹ മേഘം: സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സമൂഹ മേഘംയും വിർച്വലൈസേഷൻയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സമൂഹ മേഘം: സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക','വിർച്വലൈസേഷൻ: ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ','വിർച്വൽ യന്ത്രം: ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം','സേവന നിലവാര കരാർ: സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ'],'സമൂഹ മേഘം; വിർച്വലൈസേഷൻ','സമൂഹ മേഘം: സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക. വിർച്വലൈസേഷൻ: ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വിർച്വലൈസേഷൻയും വിർച്വൽ യന്ത്രംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വിർച്വലൈസേഷൻ: ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ','വിർച്വൽ യന്ത്രം: ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം','കണ്ടെയ്നർ: പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം','വിഭവ നിരീക്ഷണം: കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം'],'വിർച്വലൈസേഷൻ; വിർച്വൽ യന്ത്രം','വിർച്വലൈസേഷൻ: ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ. വിർച്വൽ യന്ത്രം: ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വിർച്വൽ യന്ത്രംയും കണ്ടെയ്നർയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വിർച്വൽ യന്ത്രം: ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം','കണ്ടെയ്നർ: പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം','കണ്ടെയ്നർ ക്രമീകരണം: പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം','മേഘ സംഭരണം: ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം'],'വിർച്വൽ യന്ത്രം; കണ്ടെയ്നർ','വിർച്വൽ യന്ത്രം: ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം. കണ്ടെയ്നർ: പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ കണ്ടെയ്നർയും കണ്ടെയ്നർ ക്രമീകരണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['കണ്ടെയ്നർ: പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം','കണ്ടെയ്നർ ക്രമീകരണം: പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം','സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി: ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്','വസ്തു സംഭരണം: ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക'],'കണ്ടെയ്നർ; കണ്ടെയ്നർ ക്രമീകരണം','കണ്ടെയ്നർ: പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം. കണ്ടെയ്നർ ക്രമീകരണം: പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ കണ്ടെയ്നർ ക്രമീകരണംയും സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷിയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['കണ്ടെയ്നർ ക്രമീകരണം: പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം','സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി: ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്','വിഭവ വികസനം: കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി','ഫയൽ സംഭരണം: ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക'],'കണ്ടെയ്നർ ക്രമീകരണം; സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി','കണ്ടെയ്നർ ക്രമീകരണം: പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം. സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി: ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷിയും വിഭവ വികസനംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി: ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്','വിഭവ വികസനം: കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി','വിഭവ വ്യാപനം: കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി','ഖണ്ഡ സംഭരണം: ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക'],'സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി; വിഭവ വികസനം','സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി: ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്. വിഭവ വികസനം: കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വിഭവ വികസനംയും വിഭവ വ്യാപനംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വിഭവ വികസനം: കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി','വിഭവ വ്യാപനം: കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി','ഭാരം വിതരണം: പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി','മേഘ ശൃംഖല: മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല'],'വിഭവ വികസനം; വിഭവ വ്യാപനം','വിഭവ വികസനം: കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി. വിഭവ വ്യാപനം: കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വിഭവ വ്യാപനംയും ഭാരം വിതരണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വിഭവ വ്യാപനം: കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി','ഭാരം വിതരണം: പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി','ലഭ്യത: ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ','സ്വകാര്യ ശൃംഖല: ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി'],'വിഭവ വ്യാപനം; ഭാരം വിതരണം','വിഭവ വ്യാപനം: കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി. ഭാരം വിതരണം: പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഭാരം വിതരണംയും ലഭ്യതയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഭാരം വിതരണം: പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി','ലഭ്യത: ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ','വിശ്വാസ്യത: ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്','ഉപശൃംഖല: വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം'],'ഭാരം വിതരണം; ലഭ്യത','ഭാരം വിതരണം: പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി. ലഭ്യത: ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ലഭ്യതയും വിശ്വാസ്യതയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ലഭ്യത: ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ','വിശ്വാസ്യത: ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്','സേവന നിലവാര കരാർ: സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ','അഗ്നിരോധ മതിൽ: അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം'],'ലഭ്യത; വിശ്വാസ്യത','ലഭ്യത: ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ. വിശ്വാസ്യത: ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വിശ്വാസ്യതയും സേവന നിലവാര കരാർയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വിശ്വാസ്യത: ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്','സേവന നിലവാര കരാർ: സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ','വിഭവ നിരീക്ഷണം: കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം','അനുമതി നിയന്ത്രണം: ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം'],'വിശ്വാസ്യത; സേവന നിലവാര കരാർ','വിശ്വാസ്യത: ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്. സേവന നിലവാര കരാർ: സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സേവന നിലവാര കരാർയും വിഭവ നിരീക്ഷണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സേവന നിലവാര കരാർ: സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ','വിഭവ നിരീക്ഷണം: കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം','മേഘ സംഭരണം: ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം','തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ'],'സേവന നിലവാര കരാർ; വിഭവ നിരീക്ഷണം','സേവന നിലവാര കരാർ: സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ. വിഭവ നിരീക്ഷണം: കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വിഭവ നിരീക്ഷണംയും മേഘ സംഭരണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വിഭവ നിരീക്ഷണം: കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം','മേഘ സംഭരണം: ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം','വസ്തു സംഭരണം: ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിച്ച് ഉപയോക്താവിനെ സ്ഥിരീകരിക്കുന്ന രീതി'],'വിഭവ നിരീക്ഷണം; മേഘ സംഭരണം','വിഭവ നിരീക്ഷണം: കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം. മേഘ സംഭരണം: ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ മേഘ സംഭരണംയും വസ്തു സംഭരണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['മേഘ സംഭരണം: ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം','വസ്തു സംഭരണം: ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','ഫയൽ സംഭരണം: ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','ഡാറ്റ എൻക്രിപ്ഷൻ: ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി'],'മേഘ സംഭരണം; വസ്തു സംഭരണം','മേഘ സംഭരണം: ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം. വസ്തു സംഭരണം: ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വസ്തു സംഭരണംയും ഫയൽ സംഭരണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വസ്തു സംഭരണം: ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','ഫയൽ സംഭരണം: ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','ഖണ്ഡ സംഭരണം: ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','ഡാറ്റ പകർപ്പ്: ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി'],'വസ്തു സംഭരണം; ഫയൽ സംഭരണം','വസ്തു സംഭരണം: ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക. ഫയൽ സംഭരണം: ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഫയൽ സംഭരണംയും ഖണ്ഡ സംഭരണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഫയൽ സംഭരണം: ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','ഖണ്ഡ സംഭരണം: ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','മേഘ ശൃംഖല: മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല','ബാക്കപ്പ്: വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ'],'ഫയൽ സംഭരണം; ഖണ്ഡ സംഭരണം','ഫയൽ സംഭരണം: ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക. ഖണ്ഡ സംഭരണം: ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഖണ്ഡ സംഭരണംയും മേഘ ശൃംഖലയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഖണ്ഡ സംഭരണം: ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','മേഘ ശൃംഖല: മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല','സ്വകാര്യ ശൃംഖല: ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി','ദുരന്ത വീണ്ടെടുക്കൽ: വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം'],'ഖണ്ഡ സംഭരണം; മേഘ ശൃംഖല','ഖണ്ഡ സംഭരണം: ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക. മേഘ ശൃംഖല: മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ മേഘ ശൃംഖലയും സ്വകാര്യ ശൃംഖലയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['മേഘ ശൃംഖല: മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല','സ്വകാര്യ ശൃംഖല: ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി','ഉപശൃംഖല: വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം','പ്രവർത്തന തുടർച്ച: തടസ്സങ്ങൾ ഉണ്ടായാലും പ്രധാന സേവനങ്ങൾ തുടരാൻ സഹായിക്കുന്ന പദ്ധതി'],'മേഘ ശൃംഖല; സ്വകാര്യ ശൃംഖല','മേഘ ശൃംഖല: മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല. സ്വകാര്യ ശൃംഖല: ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സ്വകാര്യ ശൃംഖലയും ഉപശൃംഖലയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സ്വകാര്യ ശൃംഖല: ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി','ഉപശൃംഖല: വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം','അഗ്നിരോധ മതിൽ: അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം','മേഘ കുടിയേറ്റം: പ്രയോഗങ്ങളെയോ ഡാറ്റയെയോ മേഘ പരിസ്ഥിതിയിലേക്ക് മാറ്റുന്ന പ്രക്രിയ'],'സ്വകാര്യ ശൃംഖല; ഉപശൃംഖല','സ്വകാര്യ ശൃംഖല: ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി. ഉപശൃംഖല: വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഉപശൃംഖലയും അഗ്നിരോധ മതിൽയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഉപശൃംഖല: വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം','അഗ്നിരോധ മതിൽ: അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം','അനുമതി നിയന്ത്രണം: ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം','മേഘ ചെലവ് നിയന്ത്രണം: മേഘ വിഭവങ്ങളുടെ ഉപയോഗവും ചെലവും കാര്യക്ഷമമായി നിയന്ത്രിക്കുന്ന പ്രവർത്തനം'],'ഉപശൃംഖല; അഗ്നിരോധ മതിൽ','ഉപശൃംഖല: വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം. അഗ്നിരോധ മതിൽ: അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ അഗ്നിരോധ മതിൽയും അനുമതി നിയന്ത്രണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['അഗ്നിരോധ മതിൽ: അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം','അനുമതി നിയന്ത്രണം: ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം','തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ','സർവർ രഹിത കണക്കുകൂട്ടൽ: സെർവർ പരിപാലനം ഉപയോക്താവിൽ നിന്ന് മറച്ച് ആവശ്യാനുസരണം പ്രയോഗ പ്രവർത്തനം നടത്തിക്കുന്ന മാതൃക'],'അഗ്നിരോധ മതിൽ; അനുമതി നിയന്ത്രണം','അഗ്നിരോധ മതിൽ: അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം. അനുമതി നിയന്ത്രണം: ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ അനുമതി നിയന്ത്രണംയും തിരിച്ചറിയൽ പരിശോധനയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['അനുമതി നിയന്ത്രണം: ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം','തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ','ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിച്ച് ഉപയോക്താവിനെ സ്ഥിരീകരിക്കുന്ന രീതി','അറ്റ കണക്കുകൂട്ടൽ: ഡാറ്റയുടെ ഉറവിടത്തിന് സമീപം കണക്കുകൂട്ടൽ നടത്തിക്കുന്ന രീതി'],'അനുമതി നിയന്ത്രണം; തിരിച്ചറിയൽ പരിശോധന','അനുമതി നിയന്ത്രണം: ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം. തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ തിരിച്ചറിയൽ പരിശോധനയും ബഹുഘടക തിരിച്ചറിയൽയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ','ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിച്ച് ഉപയോക്താവിനെ സ്ഥിരീകരിക്കുന്ന രീതി','ഡാറ്റ എൻക്രിപ്ഷൻ: ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി','മേഘ കണക്കുകൂട്ടൽ: ഇന്റർനെറ്റ് വഴി കണക്കുകൂട്ടൽ വിഭവങ്ങൾ ആവശ്യാനുസരണം ഉപയോഗിക്കുന്ന രീതി'],'തിരിച്ചറിയൽ പരിശോധന; ബഹുഘടക തിരിച്ചറിയൽ','തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ. ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിച്ച് ഉപയോക്താവിനെ സ്ഥിരീകരിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ബഹുഘടക തിരിച്ചറിയൽയും ഡാറ്റ എൻക്രിപ്ഷൻയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിച്ച് ഉപയോക്താവിനെ സ്ഥിരീകരിക്കുന്ന രീതി','ഡാറ്റ എൻക്രിപ്ഷൻ: ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി','ഡാറ്റ പകർപ്പ്: ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി','സേവനമായി അടിസ്ഥാനസൗകര്യം: കണക്കുകൂട്ടൽ യന്ത്രങ്ങൾ സംഭരണം ശൃംഖല തുടങ്ങിയ അടിസ്ഥാന വിഭവങ്ങൾ സേവനമായി ലഭ്യമാക്കുന്ന മാതൃക'],'ബഹുഘടക തിരിച്ചറിയൽ; ഡാറ്റ എൻക്രിപ്ഷൻ','ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിച്ച് ഉപയോക്താവിനെ സ്ഥിരീകരിക്കുന്ന രീതി. ഡാറ്റ എൻക്രിപ്ഷൻ: ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഡാറ്റ എൻക്രിപ്ഷൻയും ഡാറ്റ പകർപ്പ്യും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഡാറ്റ എൻക്രിപ്ഷൻ: ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി','ഡാറ്റ പകർപ്പ്: ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി','ബാക്കപ്പ്: വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ','സേവനമായി വേദി: പ്രയോഗങ്ങൾ വികസിപ്പിക്കാനും പ്രവർത്തിപ്പിക്കാനും ആവശ്യമായ വേദി സേവനമായി നൽകുന്ന മാതൃക'],'ഡാറ്റ എൻക്രിപ്ഷൻ; ഡാറ്റ പകർപ്പ്','ഡാറ്റ എൻക്രിപ്ഷൻ: ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി. ഡാറ്റ പകർപ്പ്: ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഡാറ്റ പകർപ്പ്യും ബാക്കപ്പ്യും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഡാറ്റ പകർപ്പ്: ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി','ബാക്കപ്പ്: വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ','ദുരന്ത വീണ്ടെടുക്കൽ: വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം','സേവനമായി സോഫ്റ്റ്‌വെയർ: സജ്ജമായ പ്രയോഗം സേവനമായി ഉപയോഗിക്കാൻ നൽകുന്ന മാതൃക'],'ഡാറ്റ പകർപ്പ്; ബാക്കപ്പ്','ഡാറ്റ പകർപ്പ്: ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി. ബാക്കപ്പ്: വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ബാക്കപ്പ്യും ദുരന്ത വീണ്ടെടുക്കൽയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ബാക്കപ്പ്: വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ','ദുരന്ത വീണ്ടെടുക്കൽ: വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം','പ്രവർത്തന തുടർച്ച: തടസ്സങ്ങൾ ഉണ്ടായാലും പ്രധാന സേവനങ്ങൾ തുടരാൻ സഹായിക്കുന്ന പദ്ധതി','പൊതു മേഘം: പല ഉപയോക്താക്കൾക്കും പങ്കിട്ട അടിസ്ഥാനസൗകര്യത്തിൽ ലഭ്യമാകുന്ന മേഘ മാതൃക'],'ബാക്കപ്പ്; ദുരന്ത വീണ്ടെടുക്കൽ','ബാക്കപ്പ്: വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ. ദുരന്ത വീണ്ടെടുക്കൽ: വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ദുരന്ത വീണ്ടെടുക്കൽയും പ്രവർത്തന തുടർച്ചയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ദുരന്ത വീണ്ടെടുക്കൽ: വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം','പ്രവർത്തന തുടർച്ച: തടസ്സങ്ങൾ ഉണ്ടായാലും പ്രധാന സേവനങ്ങൾ തുടരാൻ സഹായിക്കുന്ന പദ്ധതി','മേഘ കുടിയേറ്റം: പ്രയോഗങ്ങളെയോ ഡാറ്റയെയോ മേഘ പരിസ്ഥിതിയിലേക്ക് മാറ്റുന്ന പ്രക്രിയ','സ്വകാര്യ മേഘം: ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക'],'ദുരന്ത വീണ്ടെടുക്കൽ; പ്രവർത്തന തുടർച്ച','ദുരന്ത വീണ്ടെടുക്കൽ: വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം. പ്രവർത്തന തുടർച്ച: തടസ്സങ്ങൾ ഉണ്ടായാലും പ്രധാന സേവനങ്ങൾ തുടരാൻ സഹായിക്കുന്ന പദ്ധതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'സ്വകാര്യ മേഘം എന്നത് ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'മിശ്ര മേഘം എന്നത് പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'സമൂഹ മേഘം എന്നത് സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'വിർച്വലൈസേഷൻ എന്നത് ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'വിർച്വൽ യന്ത്രം എന്നത് ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'കണ്ടെയ്നർ എന്നത് പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'കണ്ടെയ്നർ ക്രമീകരണം എന്നത് പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി എന്നത് ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ് എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'വിഭവ വികസനം എന്നത് കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'വിഭവ വ്യാപനം എന്നത് കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'ഭാരം വിതരണം എന്നത് പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'ലഭ്യത എന്നത് ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'വിശ്വാസ്യത എന്നത് ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ് എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'സേവന നിലവാര കരാർ എന്നത് സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'വിഭവ നിരീക്ഷണം എന്നത് കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം.');
