INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'ഡാറ്റ എൻക്രിപ്ഷൻ എന്നത് ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'ഡാറ്റ പകർപ്പ് എന്നത് ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'ബാക്കപ്പ് എന്നത് വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'ദുരന്ത വീണ്ടെടുക്കൽ എന്നത് വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'പ്രവർത്തന തുടർച്ച എന്നത് തടസ്സങ്ങൾ ഉണ്ടായാലും പ്രധാന സേവനങ്ങൾ തുടരാൻ സഹായിക്കുന്ന പദ്ധതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. തടസ്സങ്ങൾ ഉണ്ടായാലും പ്രധാന സേവനങ്ങൾ തുടരാൻ സഹായിക്കുന്ന പദ്ധതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'മേഘ കുടിയേറ്റം എന്നത് പ്രയോഗങ്ങളെയോ ഡാറ്റയെയോ മേഘ പരിസ്ഥിതിയിലേക്ക് മാറ്റുന്ന പ്രക്രിയ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. പ്രയോഗങ്ങളെയോ ഡാറ്റയെയോ മേഘ പരിസ്ഥിതിയിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'മേഘ ചെലവ് നിയന്ത്രണം എന്നത് മേഘ വിഭവങ്ങളുടെ ഉപയോഗവും ചെലവും കാര്യക്ഷമമായി നിയന്ത്രിക്കുന്ന പ്രവർത്തനം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. മേഘ വിഭവങ്ങളുടെ ഉപയോഗവും ചെലവും കാര്യക്ഷമമായി നിയന്ത്രിക്കുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'സർവർ രഹിത കണക്കുകൂട്ടൽ എന്നത് സെർവർ പരിപാലനം ഉപയോക്താവിൽ നിന്ന് മറച്ച് ആവശ്യാനുസരണം പ്രയോഗ പ്രവർത്തനം നടത്തിക്കുന്ന മാതൃക എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സെർവർ പരിപാലനം ഉപയോക്താവിൽ നിന്ന് മറച്ച് ആവശ്യാനുസരണം പ്രയോഗ പ്രവർത്തനം നടത്തിക്കുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','True/False','Easy',1,'അറ്റ കണക്കുകൂട്ടൽ എന്നത് ഡാറ്റയുടെ ഉറവിടത്തിന് സമീപം കണക്കുകൂട്ടൽ നടത്തിക്കുന്ന രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഡാറ്റയുടെ ഉറവിടത്തിന് സമീപം കണക്കുകൂട്ടൽ നടത്തിക്കുന്ന രീതി.');
