INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Fill in the Blanks','Easy',1,'സെർവർ പരിപാലനം ഉപയോക്താവിൽ നിന്ന് മറച്ച് ആവശ്യാനുസരണം പ്രയോഗ പ്രവർത്തനം നടത്തിക്കുന്ന മാതൃക എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'സർവർ രഹിത കണക്കുകൂട്ടൽ','ശരിയായ പദം സർവർ രഹിത കണക്കുകൂട്ടൽ ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Fill in the Blanks','Easy',1,'ഡാറ്റയുടെ ഉറവിടത്തിന് സമീപം കണക്കുകൂട്ടൽ നടത്തിക്കുന്ന രീതി എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'അറ്റ കണക്കുകൂട്ടൽ','ശരിയായ പദം അറ്റ കണക്കുകൂട്ടൽ ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'മേഘ കണക്കുകൂട്ടൽ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഇന്റർനെറ്റ് വഴി കണക്കുകൂട്ടൽ വിഭവങ്ങൾ ആവശ്യാനുസരണം ഉപയോഗിക്കുന്ന രീതി','മേഘ കണക്കുകൂട്ടൽ: ഇന്റർനെറ്റ് വഴി കണക്കുകൂട്ടൽ വിഭവങ്ങൾ ആവശ്യാനുസരണം ഉപയോഗിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'സേവനമായി അടിസ്ഥാനസൗകര്യം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'കണക്കുകൂട്ടൽ യന്ത്രങ്ങൾ സംഭരണം ശൃംഖല തുടങ്ങിയ അടിസ്ഥാന വിഭവങ്ങൾ സേവനമായി ലഭ്യമാക്കുന്ന മാതൃക','സേവനമായി അടിസ്ഥാനസൗകര്യം: കണക്കുകൂട്ടൽ യന്ത്രങ്ങൾ സംഭരണം ശൃംഖല തുടങ്ങിയ അടിസ്ഥാന വിഭവങ്ങൾ സേവനമായി ലഭ്യമാക്കുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'സേവനമായി വേദി എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'പ്രയോഗങ്ങൾ വികസിപ്പിക്കാനും പ്രവർത്തിപ്പിക്കാനും ആവശ്യമായ വേദി സേവനമായി നൽകുന്ന മാതൃക','സേവനമായി വേദി: പ്രയോഗങ്ങൾ വികസിപ്പിക്കാനും പ്രവർത്തിപ്പിക്കാനും ആവശ്യമായ വേദി സേവനമായി നൽകുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'സേവനമായി സോഫ്റ്റ്‌വെയർ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'സജ്ജമായ പ്രയോഗം സേവനമായി ഉപയോഗിക്കാൻ നൽകുന്ന മാതൃക','സേവനമായി സോഫ്റ്റ്‌വെയർ: സജ്ജമായ പ്രയോഗം സേവനമായി ഉപയോഗിക്കാൻ നൽകുന്ന മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'പൊതു മേഘം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'പല ഉപയോക്താക്കൾക്കും പങ്കിട്ട അടിസ്ഥാനസൗകര്യത്തിൽ ലഭ്യമാകുന്ന മേഘ മാതൃക','പൊതു മേഘം: പല ഉപയോക്താക്കൾക്കും പങ്കിട്ട അടിസ്ഥാനസൗകര്യത്തിൽ ലഭ്യമാകുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'സ്വകാര്യ മേഘം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക','സ്വകാര്യ മേഘം: ഒരു സ്ഥാപനത്തിനായി സമർപ്പിതമായി നിയന്ത്രിക്കുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'മിശ്ര മേഘം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക','മിശ്ര മേഘം: പൊതു മേഘവും സ്വകാര്യ മേഘവും ചേർന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'സമൂഹ മേഘം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക','സമൂഹ മേഘം: സമാന ആവശ്യങ്ങളുള്ള പല സ്ഥാപനങ്ങളും പങ്കിടുന്ന മേഘ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'വിർച്വലൈസേഷൻ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ','വിർച്വലൈസേഷൻ: ഒരു ഭൗതിക വിഭവത്തെ പല സ്വതന്ത്ര താർക്കിക വിഭവങ്ങളായി ഉപയോഗിക്കുന്ന സാങ്കേതികവിദ്യ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'വിർച്വൽ യന്ത്രം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം','വിർച്വൽ യന്ത്രം: ഭൗതിക യന്ത്രത്തിനുള്ളിൽ സ്വതന്ത്ര കമ്പ്യൂട്ടർ പരിസ്ഥിതിയായി പ്രവർത്തിക്കുന്ന യന്ത്രം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'കണ്ടെയ്നർ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം','കണ്ടെയ്നർ: പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'കണ്ടെയ്നർ ക്രമീകരണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം','കണ്ടെയ്നർ ക്രമീകരണം: പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്','സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി: ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'വിഭവ വികസനം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി','വിഭവ വികസനം: കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'വിഭവ വ്യാപനം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി','വിഭവ വ്യാപനം: കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'ഭാരം വിതരണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി','ഭാരം വിതരണം: പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'ലഭ്യത എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ','ലഭ്യത: ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'വിശ്വാസ്യത എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്','വിശ്വാസ്യത: ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'സേവന നിലവാര കരാർ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ','സേവന നിലവാര കരാർ: സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'വിഭവ നിരീക്ഷണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം','വിഭവ നിരീക്ഷണം: കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'മേഘ സംഭരണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം','മേഘ സംഭരണം: ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'വസ്തു സംഭരണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','വസ്തു സംഭരണം: ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'ഫയൽ സംഭരണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','ഫയൽ സംഭരണം: ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'ഖണ്ഡ സംഭരണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക','ഖണ്ഡ സംഭരണം: ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'മേഘ ശൃംഖല എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല','മേഘ ശൃംഖല: മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'സ്വകാര്യ ശൃംഖല എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി','സ്വകാര്യ ശൃംഖല: ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'ഉപശൃംഖല എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം','ഉപശൃംഖല: വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'അഗ്നിരോധ മതിൽ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം','അഗ്നിരോധ മതിൽ: അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'അനുമതി നിയന്ത്രണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം','അനുമതി നിയന്ത്രണം: ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Short Answer','Medium',3,'തിരിച്ചറിയൽ പരിശോധന എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ','തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'കണ്ടെയ്നർ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'കണ്ടെയ്നർ എന്നത് പ്രയോഗവും അതിന്റെ ആവശ്യമായ ഘടകങ്ങളും വേർതിരിച്ച പരിസ്ഥിതിയിൽ പ്രവർത്തിപ്പിക്കുന്ന ഘടകം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','കണ്ടെയ്നർ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'കണ്ടെയ്നർ ക്രമീകരണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'കണ്ടെയ്നർ ക്രമീകരണം എന്നത് പല കണ്ടെയ്നറുകളുടെ വിന്യാസവും പ്രവർത്തനവും സ്വയമേവ നിയന്ത്രിക്കുന്ന സംവിധാനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','കണ്ടെയ്നർ ക്രമീകരണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി എന്നത് ആവശ്യത്തിന് അനുസരിച്ച് വിഭവങ്ങളുടെ അളവ് സ്വയം കൂട്ടുകയോ കുറയ്ക്കുകയോ ചെയ്യുന്ന കഴിവ്. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സ്വയമേവ വികസിക്കുന്ന വിഭവശേഷി മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'വിഭവ വികസനം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'വിഭവ വികസനം എന്നത് കൂടുതൽ വിഭവങ്ങൾ ചേർത്ത് ഒരേ സേവനത്തിന്റെ ശേഷി വർധിപ്പിക്കുന്ന രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','വിഭവ വികസനം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'വിഭവ വ്യാപനം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'വിഭവ വ്യാപനം എന്നത് കൂടുതൽ പ്രവർത്തന ഘടകങ്ങൾ ചേർത്ത് സേവന ശേഷി വർധിപ്പിക്കുന്ന രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','വിഭവ വ്യാപനം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'ഭാരം വിതരണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഭാരം വിതരണം എന്നത് പ്രവർത്തന അഭ്യർത്ഥനകൾ പല പ്രവർത്തന ഘടകങ്ങളിലേക്ക് പങ്കിടുന്ന രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഭാരം വിതരണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'ലഭ്യത വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ലഭ്യത എന്നത് ഒരു സേവനം ആവശ്യമായ സമയത്ത് ഉപയോഗിക്കാനാകുന്ന അവസ്ഥ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ലഭ്യത മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'വിശ്വാസ്യത വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'വിശ്വാസ്യത എന്നത് ഒരു സേവനം സ്ഥിരമായി ശരിയായി പ്രവർത്തിക്കാനുള്ള കഴിവ്. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','വിശ്വാസ്യത മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'സേവന നിലവാര കരാർ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സേവന നിലവാര കരാർ എന്നത് സേവനത്തിന്റെ ലഭ്യതയും പ്രകടനവും സംബന്ധിച്ച പ്രതിബദ്ധത വ്യക്തമാക്കുന്ന കരാർ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സേവന നിലവാര കരാർ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'വിഭവ നിരീക്ഷണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'വിഭവ നിരീക്ഷണം എന്നത് കണക്കുകൂട്ടൽ വിഭവങ്ങളുടെ ഉപയോഗവും നിലയും തുടർച്ചയായി പരിശോധിക്കുന്ന പ്രവർത്തനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','വിഭവ നിരീക്ഷണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'മേഘ സംഭരണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'മേഘ സംഭരണം എന്നത് ദൂരസ്ഥ മേഘ അടിസ്ഥാനസൗകര്യത്തിൽ ഡാറ്റ സൂക്ഷിക്കുന്ന സംവിധാനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','മേഘ സംഭരണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'വസ്തു സംഭരണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'വസ്തു സംഭരണം എന്നത് ഡാറ്റയെ സ്വതന്ത്ര വസ്തുക്കളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','വസ്തു സംഭരണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'ഫയൽ സംഭരണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഫയൽ സംഭരണം എന്നത് ക്രമബദ്ധമായ ഫയൽ ഘടന ഉപയോഗിച്ച് ഡാറ്റ സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഫയൽ സംഭരണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'ഖണ്ഡ സംഭരണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഖണ്ഡ സംഭരണം എന്നത് ഡാറ്റയെ നിശ്ചിത വലുപ്പത്തിലുള്ള ഖണ്ഡങ്ങളായി സൂക്ഷിക്കുന്ന സംഭരണ മാതൃക. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഖണ്ഡ സംഭരണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'മേഘ ശൃംഖല വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'മേഘ ശൃംഖല എന്നത് മേഘ വിഭവങ്ങൾ തമ്മിലുള്ള ആശയവിനിമയം സാധ്യമാക്കുന്ന ശൃംഖല. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','മേഘ ശൃംഖല മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'സ്വകാര്യ ശൃംഖല വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സ്വകാര്യ ശൃംഖല എന്നത് ഒരു സ്ഥാപനത്തിന്റെ മേഘ വിഭവങ്ങൾക്ക് വേർതിരിച്ച ശൃംഖല പരിസ്ഥിതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സ്വകാര്യ ശൃംഖല മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'ഉപശൃംഖല വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഉപശൃംഖല എന്നത് വലിയ ശൃംഖലയെ ചെറിയ താർക്കിക ശൃംഖലകളായി വിഭജിച്ച ഭാഗം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഉപശൃംഖല മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'അഗ്നിരോധ മതിൽ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'അഗ്നിരോധ മതിൽ എന്നത് അനുമതിയില്ലാത്ത ശൃംഖലാ പ്രവേശനം നിയന്ത്രിക്കുന്ന സുരക്ഷാ സംവിധാനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','അഗ്നിരോധ മതിൽ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'അനുമതി നിയന്ത്രണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'അനുമതി നിയന്ത്രണം എന്നത് ആർക്കെന്ത് വിഭവം ഉപയോഗിക്കാമെന്ന് നിർണ്ണയിക്കുന്ന സുരക്ഷാ സംവിധാനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','അനുമതി നിയന്ത്രണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'തിരിച്ചറിയൽ പരിശോധന വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'തിരിച്ചറിയൽ പരിശോധന എന്നത് ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കുന്ന പ്രക്രിയ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','തിരിച്ചറിയൽ പരിശോധന മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'ബഹുഘടക തിരിച്ചറിയൽ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ബഹുഘടക തിരിച്ചറിയൽ എന്നത് ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിച്ച് ഉപയോക്താവിനെ സ്ഥിരീകരിക്കുന്ന രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ബഹുഘടക തിരിച്ചറിയൽ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'ഡാറ്റ എൻക്രിപ്ഷൻ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഡാറ്റ എൻക്രിപ്ഷൻ എന്നത് ഡാറ്റയെ അനധികൃതർക്ക് വായിക്കാനാകാത്ത രൂപത്തിലേക്ക് മാറ്റുന്ന സുരക്ഷാ രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഡാറ്റ എൻക്രിപ്ഷൻ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'ഡാറ്റ പകർപ്പ് വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഡാറ്റ പകർപ്പ് എന്നത് ഡാറ്റയുടെ അധിക പകർപ്പുകൾ സൂക്ഷിച്ച് നഷ്ടസാധ്യത കുറയ്ക്കുന്ന രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഡാറ്റ പകർപ്പ് മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'ബാക്കപ്പ് വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ബാക്കപ്പ് എന്നത് വീണ്ടെടുക്കലിനായി ഡാറ്റയുടെ സുരക്ഷിത പകർപ്പ് സൂക്ഷിക്കൽ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ബാക്കപ്പ് മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'ദുരന്ത വീണ്ടെടുക്കൽ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ദുരന്ത വീണ്ടെടുക്കൽ എന്നത് വലിയ തകരാറിന് ശേഷം സേവനങ്ങളും ഡാറ്റയും പുനഃസ്ഥാപിക്കുന്ന സംവിധാനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ദുരന്ത വീണ്ടെടുക്കൽ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'പ്രവർത്തന തുടർച്ച വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'പ്രവർത്തന തുടർച്ച എന്നത് തടസ്സങ്ങൾ ഉണ്ടായാലും പ്രധാന സേവനങ്ങൾ തുടരാൻ സഹായിക്കുന്ന പദ്ധതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','പ്രവർത്തന തുടർച്ച മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'മേഘ കുടിയേറ്റം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'മേഘ കുടിയേറ്റം എന്നത് പ്രയോഗങ്ങളെയോ ഡാറ്റയെയോ മേഘ പരിസ്ഥിതിയിലേക്ക് മാറ്റുന്ന പ്രക്രിയ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','മേഘ കുടിയേറ്റം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'മേഘ ചെലവ് നിയന്ത്രണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'മേഘ ചെലവ് നിയന്ത്രണം എന്നത് മേഘ വിഭവങ്ങളുടെ ഉപയോഗവും ചെലവും കാര്യക്ഷമമായി നിയന്ത്രിക്കുന്ന പ്രവർത്തനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','മേഘ ചെലവ് നിയന്ത്രണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'സർവർ രഹിത കണക്കുകൂട്ടൽ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സർവർ രഹിത കണക്കുകൂട്ടൽ എന്നത് സെർവർ പരിപാലനം ഉപയോക്താവിൽ നിന്ന് മറച്ച് ആവശ്യാനുസരണം പ്രയോഗ പ്രവർത്തനം നടത്തിക്കുന്ന മാതൃക. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സർവർ രഹിത കണക്കുകൂട്ടൽ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cloud Computing','മലയാളം','Long Answer','Hard',5,'അറ്റ കണക്കുകൂട്ടൽ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'അറ്റ കണക്കുകൂട്ടൽ എന്നത് ഡാറ്റയുടെ ഉറവിടത്തിന് സമീപം കണക്കുകൂട്ടൽ നടത്തിക്കുന്ന രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','അറ്റ കണക്കുകൂട്ടൽ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
